class Solution {
public:
    long long countBadPairs(vector<int>& nums) {
        unordered_map<int,int> cnt;
        long long good = 0;
        int n = (int)nums.size();
        for (int i = 0; i < n; i++) {
            int v = nums[i] - i;
            good += cnt[v];
            cnt[v]++;
        }
        long long total = (long long)n * (n - 1) / 2;
        return total - good;
    }
};
